%[text] # Validation - Road Grade Profile block
%[text] This script is for the visual inspection of plots and also used by unit test. After changing this script, make sure the tests continue to pass.
model_name = "HarnessModel_RoadGradeProfile_CustomComponent";
block_path = model_name + "/Road Grade Profile";
load_system(model_name)

sg = @bevutil1.CodeUtil.stringify;

sim_in = Simulink.SimulationInput(model_name);
%[text] Validation setup. 10,000 second run at 1 m/s speed yields 10,000 m in the curvilinear travel distance at the end of simulation.
sim_in = setModelParameter(sim_in, StopTime="10000");
sim_in = setBlockParameter(sim_in, model_name+"/Curvilinear Speed", "constant", "1");
sim_in = setBlockParameter(sim_in, model_name+"/Curvilinear Speed", "constant_unit", "m/s");
%[text] Specify 2 % slope. Use the "linear" option for the interpolation.
% Horizontal distance for vertical profile
sim_in = setBlockParameter(sim_in, block_path, "x_vector", sg([ -1 0 1 ]));
sim_in = setBlockParameter(sim_in, block_path, "x_vector_unit", "m");

% Road grade profile (percent) ... !validation-target
sim_in = setBlockParameter(sim_in, block_path, "grade_vector", sg([ 2 2 2 ]));  %!validation-target

% Profile interpolation method ... !validation-target
sim_in = setBlockParameter(sim_in, block_path, "profile_interp_method", "simscape.enum.interpolation.linear");
%[text] 
% Initial horizontal position
sim_in = setBlockParameter(sim_in, block_path, "initial_position", "0");
sim_in = setBlockParameter(sim_in, block_path, "initial_position_unit", "m");

% Elevation at initial horizontal position
sim_in = setBlockParameter(sim_in, block_path, "initial_elevation", "0");
sim_in = setBlockParameter(sim_in, block_path, "initial_elevation_unit", "m");

sim_out = sim(sim_in);

result = extractTimetable(sim_out.logsout);

varnames = [
"Curvilinear speed"
"Grade percent"
"Incline angle"
"Elevation"
"Horizontal position"
];

for k = 1 : numel(varnames) %[output:group:03dcdb46]
  bevutil1.SignalUtil.plotTimedData(TimedData=result, SignalName=varnames(k), FigureHeight=150); %[output:2ec063da] %[output:8c608790] %[output:7d875c5c] %[output:606ae865] %[output:16c028d9]
end  % for %[output:group:03dcdb46]
